# -*- coding: utf-8 -*-
"""Generate PULSE Pharm data for chapters 23-30 from the rendered book-page scans.

Source: uploads/Pharmacology Marrow E8 (1).pdf, book pages 89-122.
Chapters: 23 Antihypertensive Drugs (89-90), 24 Antianginal Drugs (91-93),
25 Hypolipidemic Drugs (94-100), 26 Diuretics: Part 1 (101-105),
27 Diuretics: Part 2 (106-112), 28 Antiepileptic Drugs: Part 1 (113-117),
29 Antiepileptic Drugs: Part 2 (118-119), 30 Sedative-Hypnotic Drugs (120-122).
The generator keeps question ids/units deterministic and explanations ending in (Book pX).
"""
import json
from pathlib import Path

Q = []
UNITS = []
CH = None
CUR = None

def start(ch):
    global CH, Q, UNITS, CUR
    CH = ch
    Q = []
    UNITS = []
    CUR = None

def unit(title, guide):
    global CUR
    if CUR:
        end_unit()
    CUR = {"title": title, "start": len(Q) + 1, "guide": guide}

def q(page, text, opts, exp):
    assert CUR is not None, "call unit() before q()"
    assert len(opts) == 4, opts
    assert len(set(opts)) == 4, opts
    suffix = f"(Book p{page})"
    exp = exp.rstrip()
    if not exp.endswith(suffix):
        exp = f"{exp} {suffix}"
    Q.append({"id": "", "sec": CUR["title"], "page": page, "q": text,
              "opts": opts, "ans": 0, "exp": exp})

def end_unit():
    global CUR
    if CUR is None:
        return
    CUR["end"] = len(Q)
    UNITS.append(CUR)
    CUR = None

def finish():
    end_unit()
    for i, item in enumerate(Q, 1):
        item["id"] = f"PHARM-C{CH}-{i:03d}"
    units = []
    for n, u in enumerate(UNITS, 1):
        a, b = u["start"], u["end"]
        units.append({
            "id": f"PHARM-U{CH}-{n}", "ch": CH, "n": n, "title": u["title"],
            "sec": f"{u['title']} · p{Q[a-1]['page']}",
            "qs": [f"PHARM-C{CH}-{i:03d}" for i in range(a, b + 1)],
            "guide": u["guide"],
        })
    Path("data").mkdir(exist_ok=True)
    out = Path(f"data/ch{CH:02d}.json")
    json.dump({"questions": Q, "units": units}, out.open("w", encoding="utf-8"),
              ensure_ascii=False, indent=1)
    print(f"ch{CH}: {len(Q)} questions, {len(units)} units -> {out}")
    for u in units:
        print("  ", u["id"], len(u["qs"]), u["sec"])

