q(117, 'Zonisamide is associated with:', ['Renal stones', 'Angle closure glaucoma', 'Suicidal tendencies', 'Purple glove syndrome'], 'Zonisamide S/E: renal stones.')
q(117, 'Lacosamide is associated with:', ['↑Suicidal tendencies', 'Renal stones', 'Visual field defects', 'Blue pigmentation'], 'Lacosamide S/E: up suicidal tendencies.')
