q(117, 'The drug associated with SJS and HLA B1502 is:', ['Carbamazepine', 'Abacavir', 'Allopurinol', 'Lamotrigine'], 'The note lists carbamazepine: HLA B1502.')
q(117, 'The drug associated with HLA B5701 is:', ['Abacavir', 'Carbamazepine', 'Allopurinol', 'Phenytoin'], 'The note lists abacavir: HLA B5701.')
q(117, 'The drug associated with HLA B5801 is:', ['Allopurinol', 'Abacavir', 'Carbamazepine', 'Oxcarbazepine'], 'The note lists allopurinol: HLA B5801.')
